const DEFAULT_SHORTCUTS:ShortcutMap={select:'A',switch:'Q',curtain:'W',sensor:'S',thermostat:'D',light:'R',non_smart_area:'T',lock:'F',camera:'E',ceiling_ap:'G',wall_ap:'H',water:'J',av:'K',system:'L',other:'M',delete:'Delete',undo:'Mod+Z',redo:'Mod+Shift+Z'};
const isTypingTarget=(target:EventTarget|null)=>target instanceof HTMLElement&&Boolean(target.closest('input, textarea, select, [contenteditable="true"]'));
const shortcutFromEvent=(e:{key:string,metaKey:boolean,ctrlKey:boolean,altKey:boolean,shiftKey:boolean})=>{
  if(['Meta','Control','Alt','Shift'].includes(e.key))return '';
  const key=e.key===' '?'Space':e.key.length===1?e.key.toUpperCase():e.key;
  return [...(e.metaKey||e.ctrlKey?['Mod']:[]),...(e.altKey?['Alt']:[]),...(e.shiftKey?['Shift']:[]),key].join('+');
};
const loadShortcuts=():ShortcutMap=>{try{const saved=JSON.parse(localStorage.getItem(SHORTCUT_STORAGE_KEY)||'{}');return {...DEFAULT_SHORTCUTS,...saved}}catch{return {...DEFAULT_SHORTCUTS}}};

