  const upload=async(file:File)=>{if(!file)return;const fd=new FormData();fd.append('file',file);fd.append('page',String(pageInput));fd.append('floor_id',floor.id);if(drawing?.canvas_mode==='fixed')fd.append('drawing_id',drawing.id);await run(async()=>{const d=await api<Drawing>('/projects/'+project.id+'/drawings',{method:'POST',body:fd});setDrawingId(d.id);setFramePreview(null)})};
