  const rotateMainPlan=()=>{if(!drawing||drawing.canvas_mode!=='fixed')return;const next=(imageFrame.rotation+90)%360;setFramePreview({...imageFrame,rotation:next});void run(async()=>{await patch(`/projects/${project.id}/drawings/${drawing.id}`,{image_rotation:next})}).finally(()=>setFramePreview(null))};
  const resizeMainPlan=(factor:number)=>{if(!drawing||drawing.canvas_mode!=='fixed')return;const next={...imageFrame,width:Math.max(80,Math.min(canvasWidth*4,imageFrame.width*factor)),height:Math.max(45,Math.min(canvasHeight*4,imageFrame.height*factor))};setFramePreview(next);void run(async()=>{await patch(`/projects/${project.id}/drawings/${drawing.id}`,{image_width:next.width,image_height:next.height})}).finally(()=>setFramePreview(null))};
  const cropMainPlan=()=>{if(!drawing||drawing.canvas_mode!=='fixed'||drawing.is_blank)return;if(tool==='crop'){setCropPreview(null);setTool('select');return}if(Math.abs(imageFrame.rotation%360)>0){fail(new Error('请先将主图纸旋转回正（0°）再裁剪'));return}setCropPreview({...cropBounds});setTool('crop')};const applyCrop=(bounds=cropPreview||cropBounds)=>{if(!drawing||!bounds)return;void run(async()=>{await post(`/projects/${project.id}/drawings/${drawing.id}/crop`,bounds);setTool('select');setCropPreview(null)})};const restoreCrop=()=>applyCrop({left:0,top:0,right:1,bottom:1});
  const addReferenceGuide=(axis:'x'|'y')=>{if(!drawing||drawing.canvas_mode!=='fixed')return;const raw=prompt(axis==='x'?'垂直参考线位置（画布百分比 0–100）':'水平参考线位置（画布百分比 0–100）','50');if(raw===null)return;const n=Number(raw);if(!Number.isFinite(n)||n<0||n>100){fail(new Error('位置请输入 0 到 100 之间的数字'));return}const next=[...guideLines,{axis,position:n/100}];setGuidePreview(next);void run(async()=>{await patch(`/projects/${project.id}/drawings/${drawing.id}`,{guide_lines:next})}).finally(()=>setGuidePreview(null))};
