  const guidePositionAt=(axis:'x'|'y',clientX:number,clientY:number)=>{const pos=screenToCanvas(clientX,clientY),length=axis==='x'?canvasWidth:canvasHeight,raw=Math.max(0,Math.min(1,(axis==='x'?pos.x:pos.y)/length)),candidates=[0,.5,1,...guideLines.filter(g=>g.axis===axis).map(g=>g.position)];const angle=imageFrame.rotation*Math.PI/180,c=Math.cos(angle),sn=Math.sin(angle);for(const point of visiblePoints){const px=imageFrame.x+imageFrame.width*point.x,py=imageFrame.y+imageFrame.height*point.y,cx=imageFrame.x+imageFrame.width/2,cy=imageFrame.y+imageFrame.height/2,rx=cx+(px-cx)*c-(py-cy)*sn,ry=cy+(px-cx)*sn+(py-cy)*c;candidates.push((axis==='x'?rx:ry)/length)}const tolerance=14/(Math.max(.2,fit*zoom)*length);let best=raw,bestDistance=tolerance;for(const candidate of candidates){if(candidate<0||candidate>1)continue;const distance=Math.abs(candidate-raw);if(distance<bestDistance){best=candidate;bestDistance=distance}}return best};
