  const downNewGuide=(e:React.PointerEvent<HTMLDivElement>,axis:'x'|'y')=>{if(e.button!==0)return;e.stopPropagation();pointer.current={mode:'new-guide',axis};e.currentTarget.setPointerCapture(e.pointerId);setGuidePreview([...guideLines,{axis,position:guidePositionAt(axis,e.clientX,e.clientY)}])};
